import java.io.*;
import java.util.*;

class Solution {
    public int projectionArea(int[][] grid) {
        int n = grid.length;
        int area = 0;
        for (int i = 0; i < n; i++) {
            int rowMax = 0;
            int colMax = 0;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) area++;
                rowMax = Math.max(rowMax, grid[i][j]);
                colMax = Math.max(colMax, grid[j][i]);
            }
            area += rowMax + colMax;
        }
        return area;
    }

    private static int[][] parseGrid(String input) {
        String s = input.replaceAll("[^0-9]+", " ").trim();
        if (s.isEmpty()) return new int[0][0];
        String[] parts = s.split("\\s+");
        int count = parts.length;
        int n = (int)Math.sqrt(count);
        int[][] grid = new int[n][n];
        for (int i = 0; i < count; i++) {
            grid[i / n][i % n] = Integer.parseInt(parts[i]);
        }
        return grid;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String input = br.readLine();
        int[][] grid = parseGrid(input);
        System.out.println(new Solution().projectionArea(grid));
    }
}

